def lcs(a, b):
    dp = [[0]*(len(b)+1) for _ in range(len(a)+1)]
    for i in range(len(a)):
        for j in range(len(b)):
            dp[i+1][j+1] = dp[i][j]+1 if a[i] == b[j] else max(dp[i][j+1], dp[i+1][j])
    return dp[-1][-1]
def rouge_l(a, b):
    a, b = a.split(), b.split(); l = lcs(a, b)
    if l == 0: return 0.0
    p, r = l/len(b), l/len(a); return 2*p*r/(p+r)
pool = ['에어컨 온도를 22도로 맞춰줘']
for cand in ['에어컨 온도를 21도로 맞춰줘', '운전석 창문 반만 열어줘']:
    s = max(rouge_l(cand, p) for p in pool)
    print(cand, round(s, 3), 'drop' if s >= 0.7 else 'keep')
# 에어컨 온도를 21도로 맞춰줘 0.75 drop
# 운전석 창문 반만 열어줘 0.0 keep
